      "content": "import { render, screen } from '@testing-library/react';
import PricingPage from '@/app/pricing/page';
import userEvent from '@testing-library/user-event';

describe('PricingPage accessibility', () => {
  it('renders three pricing plans', () => {
    render(<PricingPage />);
    expect(screen.getByText('Basic')).toBeInTheDocument();
    expect(screen.getByText('Pro')).toBeInTheDocument();
    expect(screen.getByText('Enterprise')).toBeInTheDocument();
  });

  it('CTAs are focusable and keyboard-accessible', async () => {
    render(<PricingPage />);
    const buttons = screen.getAllByRole('button', { name: /choose/i });
    expect(buttons.length).toBe(3);
    await userEvent.tab(); // focus first CTA
    expect(buttons[0]).toHaveFocus();
  });

  it('feature table is accessible', () => {
    render(<PricingPage />);
    expect(screen.getByRole('table', { name: /feature comparison/i })).toBeInTheDocument();
    expect(screen.getByText('Feature A')).toBeInTheDocument();
  });
});
